{
  "plan_name": "arcgis-buffer-plan",
  "status": "NOT_EXECUTED",
  "note": "This is a dry-run tool plan for arcgis-mcp-bridge only. No bridge connection was opened and no tool was called to produce this file. Tool names/parameters below follow the skill's tool-routing snapshot and standard ArcPy analysis.Buffer semantics; they must be re-verified against the live MCP schema (list_tools / tool description) before any execution.",
  "objective": "Reproject the EPSG:4326 roads layer to EPSG:32635 (UTM 35N) and produce a single 750 m dissolved buffer polygon output in scratch.gdb, leaving the source roads layer untouched.",
  "contract": {
    "source": {
      "path": "<path-to-source-roads-feature-class>",
      "declared_crs": "EPSG:4326",
      "mutation_policy": "read-only; must remain byte-for-byte unchanged (no overwrite, no in-place edit, no define_projection)"
    },
    "target_crs": "EPSG:32635",
    "buffer_distance": "750 Meters",
    "dissolve_option": "ALL",
    "output_workspace": "<allowed-root>/scratch.gdb",
    "aprx_change_required": false
  },
  "preflight": [
    {
      "tool": "health_check",
      "purpose": "Confirm bridge worker, allowed roots, and scratch GDB configuration.",
      "mutates": false
    },
    {
      "tool": "describe_dataset",
      "params": { "dataset": "<path-to-source-roads-feature-class>" },
      "purpose": "Confirm feature type, declared CRS (expect EPSG:4326), fields, and current feature count before touching anything.",
      "mutates": false
    },
    {
      "tool": "get_spatial_reference",
      "params": { "wkid": 32635 },
      "purpose": "Resolve WGS84 / UTM zone 35N definition and confirm no ambiguous datum transformation is required (WGS84 -> WGS84 UTM is a direct projected transform, no datum shift).",
      "mutates": false
    },
    {
      "tool": "get_feature_count",
      "params": { "dataset": "<path-to-source-roads-feature-class>" },
      "purpose": "Baseline count to reconcile against the projected and buffered outputs.",
      "mutates": false
    }
  ],
  "steps": [
    {
      "step": 1,
      "tool": "project_features",
      "params": {
        "in_features": "<path-to-source-roads-feature-class>",
        "out_features": "<allowed-root>/scratch.gdb/roads_32635",
        "out_coor_system": "EPSG:32635"
      },
      "creates_new_output": true,
      "mutates_source": false,
      "confirm_required": "not in the current confirm=true gated tool list, but verify against live schema before running",
      "notes": "Writes a new projected feature class; source layer is only read, never edited or overwritten."
    },
    {
      "step": 2,
      "tool": "buffer_features",
      "tool_name_unverified": true,
      "verification_note": "Not present in the tool-routing snapshot's 'Overlay and geometry' catalog (only intersect/union/erase/identity/symmetrical_difference/dissolve/merge/spatial_join/summarize_within/tabulate_intersection are listed there). Confirm the live schema's exact buffer tool name and parameter names before executing; adjust this step to match.",
      "params": {
        "in_features": "<allowed-root>/scratch.gdb/roads_32635",
        "out_feature_class": "<allowed-root>/scratch.gdb/roads_buffer_750m_dissolved",
        "buffer_distance_or_field": "750 Meters",
        "dissolve_option": "ALL"
      },
      "creates_new_output": true,
      "mutates_source": false,
      "confirm_required": "not in the current confirm=true gated tool list, but verify against live schema before running",
      "notes": "Produces one dissolved buffer polygon covering all roads at 750 m. If the live buffer tool lacks an inline dissolve_option, fall back to step 2a + 2b below."
    },
    {
      "step": "2a (fallback only, if buffer tool has no dissolve option)",
      "tool": "buffer_features",
      "params": {
        "in_features": "<allowed-root>/scratch.gdb/roads_32635",
        "out_feature_class": "<allowed-root>/scratch.gdb/roads_buffer_750m_raw",
        "buffer_distance_or_field": "750 Meters"
      },
      "creates_new_output": true,
      "mutates_source": false
    },
    {
      "step": "2b (fallback only, if buffer tool has no dissolve option)",
      "tool": "dissolve_features",
      "params": {
        "in_features": "<allowed-root>/scratch.gdb/roads_buffer_750m_raw",
        "out_feature_class": "<allowed-root>/scratch.gdb/roads_buffer_750m_dissolved"
      },
      "creates_new_output": true,
      "mutates_source": false
    }
  ],
  "verification": [
    "describe_dataset on roads_32635: spatial reference == EPSG:32635, geometry type unchanged, feature count == source baseline count.",
    "describe_dataset on roads_buffer_750m_dissolved: spatial reference == EPSG:32635, geometry type == Polygon, feature count == 1 (fully dissolved) or as expected for the chosen dissolve grouping.",
    "get_extent on the buffer output should exceed the projected roads extent by approximately the 750 m buffer distance on all sides.",
    "Re-describe the original source dataset and confirm its CRS, schema, and feature count are identical to the preflight baseline (source unchanged)."
  ],
  "authorization_notes": [
    "No step in this plan targets a confirm=true gated tool from the current bridge snapshot (append_features, calculate_field, define_projection, delete_dataset, delete_field, delete_identical, extract_sketch_to_gis, near_analysis, remove_layer_from_map, repair_geometry) and no overwrite=true is requested.",
    "All outputs are new datasets in scratch.gdb; the source roads feature class is never passed as an out_features/out_feature_class target.",
    "Placeholder paths (<path-to-source-roads-feature-class>, <allowed-root>/scratch.gdb) must be filled in with absolute paths inside ARCGIS_MCP_ALLOWED_ROOTS before execution, and scratch.gdb must already exist inside an allowed root."
  ],
  "execution_status": "This file is a plan only. No bridge tool has been invoked; no dataset has been read, projected, buffered, or dissolved."
}

{
  "title": "COVID-19 Case Rate by County",
  "message": "Case rate (not raw case count) varies across the four synthetic counties; Southeast (D) cannot be classified because its population denominator is missing.",
  "output_file": "outputs/covid-choropleth.html",
  "generated_date": "2026-08-30",
  "map_type": "choropleth",
  "self_contained": true,
  "external_dependencies": [],
  "rendering": "inline SVG + CSS + vanilla JS, no CDN/network calls, viewable by opening the HTML file directly in a browser",
  "data_sources": [
    {
      "file": "inputs/counties.geojson",
      "role": "geometry",
      "crs": "urn:ogc:def:crs:OGC:1.3:CRS84 (nominal tag on a synthetic unit-square grid; not a real-world geographic projection)",
      "join_field": "county_id"
    },
    {
      "file": "inputs/covid.csv",
      "role": "attributes",
      "fields": ["county_id", "cases", "population", "source"],
      "join_field": "county_id",
      "source_note": "Synthetic benchmark surveillance table"
    }
  ],
  "join": {
    "type": "attribute join",
    "key": "county_id",
    "left": "inputs/counties.geojson (properties.county_id)",
    "right": "inputs/covid.csv (county_id)",
    "match_rate": "4 of 4 geometries matched to 4 of 4 attribute rows"
  },
  "variable": {
    "displayed_field": "cases_per_1000",
    "formula": "cases / population * 1000",
    "units": "cases per 1,000 population",
    "normalized": true,
    "normalization_rationale": "Raw case counts were not mapped directly because they conflate incidence with county population size (a raw-count choropleth is effectively a population map in disguise)."
  },
  "classification": {
    "method": "manual (exact observed data values used as class boundaries)",
    "k": 3,
    "breaks": [5.0, 10.0, 15.0],
    "rationale": "Only 3 of 4 counties have a valid rate (n=3). Statistical binning methods such as Jenks natural breaks or quantiles are not meaningful at this sample size and would imply spurious precision, so the three observed values were used directly as class boundaries.",
    "alternative_schemes_considered": ["quantile", "equal interval"],
    "alternative_scheme_result": "With n=3 unique values, quantile and equal-interval schemes reduce to the same three classes as the manual scheme; no material difference in the story."
  },
  "color": {
    "scheme_name": "ColorBrewer YlOrRd, 3-class sequential",
    "colorblind_safe": true,
    "class_colors": [
      { "range": "5.0 – <10.0", "hex": "#ffeda0" },
      { "range": "10.0 – <15.0", "hex": "#feb24c" },
      { "range": "15.0 (highest observed)", "hex": "#f03b20" }
    ],
    "no_data_color": "#d9d9d9",
    "no_data_treatment": "Neutral gray, excluded from the sequential ramp and given its own legend entry; not treated as the lowest class or as zero."
  },
  "projection": {
    "applied": false,
    "note": "Source geometry is a synthetic unit-square grid tagged with CRS84; it does not represent a real-world location, so no map projection, scale bar, or north arrow is applicable or shown."
  },
  "counties": [
    { "county_id": "A", "name": "Northwest", "cases": 100, "population": 10000, "cases_per_1000": 10.0, "class": "10.0 – <15.0", "no_data": false },
    { "county_id": "B", "name": "Northeast", "cases": 200, "population": 40000, "cases_per_1000": 5.0, "class": "5.0 – <10.0", "no_data": false },
    { "county_id": "C", "name": "Southwest", "cases": 30, "population": 2000, "cases_per_1000": 15.0, "class": "15.0 (highest observed)", "no_data": false },
    { "county_id": "D", "name": "Southeast", "cases": 10, "population": null, "cases_per_1000": null, "class": null, "no_data": true, "no_data_reason": "population value missing in inputs/covid.csv, so a per-1,000 rate cannot be computed" }
  ],
  "accessibility": {
    "colorblind_safe_ramp": true,
    "no_data_distinguishable_from_ramp": true,
    "text_alternatives": "SVG has role=img and an aria-label describing the map; source data table duplicates all mapped values as text",
    "interaction": "hover/click on a county highlights it and shows cases, population, and rate in a text panel; no information is conveyed by color alone since labels and a table are also provided"
  },
  "verification": {
    "squint_test": "3 of 4 counties show a clear light-to-dark progression by rate; the 4th (No data) is visually distinct gray",
    "cross_check": "SVG fill colors, table values, and hover panel values all reconcile against inputs/covid.csv for all 4 counties",
    "legend_audit": "units stated (cases per 1,000 population), class edges non-overlapping, no-data has its own entry"
  }
}

{
  "specification": "change-release-spec",
  "version": "1.0",
  "title": "Land-Cover Change Area Reporting Specification for Public Statistical Release",
  "purpose": "Define the mandatory methodology, accuracy-assessment protocol, and disclosure requirements for converting two independently validated land-cover maps into publishable, error-adjusted change-area (hectares) estimates.",

  "scope": {
    "inputs": "Two categorical land-cover raster/vector maps, Map_T1 and Map_T2, each independently classified and independently validated (separate accuracy assessments, not a single classifier applied to both dates).",
    "output": "Public statistics release reporting hectares changed per class-to-class transition, with confidence intervals, suitable for external scrutiny and reuse.",
    "excludes": "Continuous index differencing (NDVI/NBR); this spec covers categorical post-classification comparison (PCC) only."
  },

  "known_risk_disclosure": {
    "id": "independent_map_pcc_error_compounding",
    "description": "Map_T1 and Map_T2 were produced and validated independently (different classifiers and/or reference samples). Post-classification comparison of two independently produced maps compounds classification error multiplicatively: two maps each at ~90% overall accuracy yield a raw change layer with accuracy at or below ~81%, and any systematic bias in either map's errors manifests as spurious transitions rather than random noise.",
    "mandatory_mitigations": [
      "Do not report raw pixel/polygon-count change areas as final figures under any circumstance; only error-adjusted estimates (see area_estimation) may appear in the release.",
      "Build and publish the full from-to transition matrix, not a change/no-change binary, so implausible transitions are visible and auditable.",
      "Flag and separately quantify 'impossible' or highly improbable transitions (e.g. water→forest in one interval) as a map-error diagnostic; exclude them from the headline change figure only after documenting the exclusion rule and its effect size.",
      "Apply one common minimum mapping unit (MMU) and one common legend crosswalk to both maps before differencing.",
      "Report the accuracy of each source map's validation alongside the compounded/propagated accuracy of the derived change product; never present the change product's implied accuracy as equal to either source map's stated accuracy."
    ]
  },

  "comparability_preconditions": {
    "legend_harmonization": {
      "requirement": "Both maps must be crosswalked to one shared class legend prior to comparison.",
      "evidence_required": "Published crosswalk table (source class -> shared class) for each map."
    },
    "co_registration": {
      "requirement": "Sub-pixel/sub-parcel spatial alignment between T1 and T2.",
      "metric": "co_registration_rmse_pixels",
      "acceptance_threshold": "<= 0.5 pixel (or documented equivalent for vector data)"
    },
    "minimum_mapping_unit": {
      "requirement": "Identical MMU applied to both maps before differencing.",
      "field": "mmu_hectares"
    },
    "spatial_extent": {
      "requirement": "Analysis restricted to the mutually valid intersection of both maps' extents; coverage percentage must be reported."
    },
    "temporal_definition": {
      "requirement": "T1 and T2 acquisition/reference dates and any compositing windows stated explicitly; seasonal mismatch documented and justified.",
      "fields": ["t1_reference_period", "t2_reference_period", "interval_years"]
    },
    "independent_validation_provenance": {
      "requirement": "Each source map's own accuracy assessment (sample design, sample size, confusion matrix, response design) must be cited and archived, not just its summary accuracy figure."
    }
  },

  "methodology": {
    "change_definition": "A location is 'changed' if its shared-legend class differs between T1 and T2 after MMU harmonization; 'unchanged' otherwise.",
    "transition_matrix": {
      "requirement": "Full square matrix of class_T1 x class_T2 areas (hectares), pixel/feature counts, and proportions.",
      "diagonal": "unchanged area per class",
      "off_diagonal": "changed area per from-to transition",
      "implausible_transition_flagging": "Each off-diagonal cell reviewed against a documented plausibility ruleset; implausible cells reported with their area and treated as a map-error indicator in accuracy_assessment.error_matrix_diagnostics."
    },
    "processing_steps": [
      "1. Harmonize legend, MMU, extent, and projection for both maps.",
      "2. Overlay to produce the from-to transition raster/polygon layer.",
      "3. Compute raw (unadjusted) transition matrix in hectares — internal QA only, never released as final numbers.",
      "4. Draw stratified accuracy-assessment sample per accuracy_assessment section.",
      "5. Apply Olofsson et al. (2014) good-practice estimator to obtain error-adjusted areas, standard errors, and confidence intervals per transition class.",
      "6. Reconcile adjusted totals against raw totals; document and explain any large divergence before release."
    ]
  },

  "accuracy_assessment": {
    "protocol": "Olofsson, Foody, Herold, Stehman, Woodcock & Wulder (2014) 'Good practices for estimating area and assessing accuracy of land change' — mandatory reference implementation.",
    "sample_design": {
      "type": "stratified random sampling",
      "strata": "Map-derived strata: one stratum per from-to transition class plus one or more 'stable/no-change' strata (never simple random sampling over all pixels, since change is rare and would be undersampled).",
      "minimum_sample_size_rule": "At least 50-100 reference samples per stratum for strata expected to occupy a small map proportion, per Olofsson et al. minimum guidance; larger, high-area strata may use proportional allocation.",
      "allocation_method": "Document whether allocation is proportional, equal, or optimized (e.g. Neyman); report the chosen rule and rationale."
    },
    "reference_data": {
      "requirement": "Reference labels collected independently of both classification processes (e.g. high-resolution imagery interpretation, field visit, or an independent third dataset), with a documented response design and blind labeling protocol.",
      "temporal_matching": "Reference data must be date-matched to T1 and T2 acquisition windows."
    },
    "confusion_matrix_by_stratum": {
      "requirement": "Report the full stratified error/confusion matrix (sample counts n_ij), not just overall accuracy.",
      "derived_metrics": [
        "user's accuracy per class (commission error complement)",
        "producer's accuracy per class (omission error complement)",
        "overall accuracy"
      ]
    },
    "error_matrix_diagnostics": {
      "implausible_transition_rate": "Proportion of mapped change area falling into pre-defined implausible transitions.",
      "compounded_error_note": "Report the derived change-layer accuracy alongside (not in place of) each source map's independently validated accuracy."
    }
  },

  "area_estimation": {
    "estimator": "Stratified error-adjusted area estimator (Olofsson et al. 2014, Eqs. 9-13)",
    "confidence_level": 0.95,
    "formulas": {
      "adjusted_proportion": "p_hat_j = sum_i( W_i * n_ij / n_i_dot )  -- W_i = mapped proportion of area in stratum i; n_ij = sample count of reference class j within stratum i; n_i_dot = total sample count in stratum i",
      "adjusted_area": "A_hat_j = A_total * p_hat_j",
      "standard_error_proportion": "SE(p_hat_j) = sqrt( sum_i( W_i^2 * (n_ij/n_i_dot) * (1 - n_ij/n_i_dot) / (n_i_dot - 1) ) )",
      "standard_error_area": "SE(A_hat_j) = A_total * SE(p_hat_j)",
      "confidence_interval": "A_hat_j +/- 1.96 * SE(A_hat_j)  (z=1.96 for 95% CI; report z explicitly if a different confidence level is used)",
      "users_accuracy": "UA_i = n_ii / n_i_dot (mapped class i, stratum-conditional)",
      "producers_accuracy": "PA_j = (W_j * n_jj / n_j_dot) / sum_i( W_i * n_ij / n_i_dot )"
    },
    "units": "hectares (converted from adjusted proportion x total study-area hectares); pixel/native units must never appear in the public release table",
    "outputs_required": [
      "adjusted_area_hectares per class and per from-to transition",
      "standard_error_hectares",
      "confidence_interval_lower_hectares",
      "confidence_interval_upper_hectares",
      "margin_of_error_percent (SE-derived, relative to adjusted area)",
      "raw_mapped_area_hectares (retained for transparency/comparison, clearly labeled as unadjusted and not the headline figure)"
    ],
    "reliability_flagging": {
      "requirement": "Any transition whose relative margin of error exceeds a defined threshold (e.g. 30% of the estimate) must be flagged as low-reliability in the release rather than presented as a precise figure.",
      "threshold_field": "reliability_moe_threshold_percent"
    }
  },

  "uncertainty_propagation": {
    "requirement": "Confidence intervals on adjusted areas must originate from the stratified estimator's sampling variance (above); do not additionally quote source-map overall accuracy as if it were the change-area CI.",
    "sensitivity_reporting": "Report adjusted area under at least two plausible implausible-transition exclusion rules (strict vs. lenient) if such filtering is applied, and state whether the conclusion (direction/magnitude of change) is stable across them."
  },

  "public_release_requirements": {
    "statistical_disclosure_control": {
      "small_cell_suppression": "Suppress or aggregate any transition cell with reference sample count n_ij below a documented minimum (e.g. n < 10) to avoid publishing statistically unsupported figures.",
      "no_individual_unit_identification": "Release must report only aggregated hectare totals per class/transition; no individual parcel-, pixel-, or feature-level attribution."
    },
    "rounding_and_precision": {
      "rule": "Round published hectare figures to a precision consistent with their standard error (e.g. no more significant figures than justified by SE); never report false precision (e.g. single-hectare precision on an estimate with a multi-thousand-hectare CI).",
      "consistency": "Apply the same rounding rule uniformly across all classes/transitions in the release table."
    },
    "metadata_documentation": {
      "required_fields": [
        "source_map_identifiers_and_versions (Map_T1, Map_T2)",
        "independent_validation_reports_for_each_source_map (citation/link)",
        "legend_crosswalk_table",
        "mmu_hectares",
        "study_area_definition_and_total_hectares",
        "reference_period_t1",
        "reference_period_t2",
        "sample_design_description",
        "estimator_and_formulas_used (this document)",
        "confidence_level",
        "known_limitations (see known_risk_disclosure)",
        "release_date",
        "point_of_contact"
      ]
    },
    "caveats_and_limitations_statement": {
      "mandatory_language_topics": [
        "Change estimates derive from two independently classified and independently validated maps; compounded classification error is inherent and quantified above.",
        "Adjusted (not raw) areas are the official statistic.",
        "Any excluded implausible transitions and their effect on totals.",
        "Coverage limited to the mutually valid overlap extent between the two maps; the excluded fraction is stated."
      ]
    },
    "versioning_and_reproducibility": {
      "requirement": "Publish the processing pipeline version, random seed (if sampling is randomized), and enough parameter detail (MMU, crosswalk, stratification, allocation) that the estimate is independently reproducible from the two source maps.",
      "revision_policy": "Any correction to source maps, crosswalk, or sample design that changes published figures must trigger a versioned re-release with a changelog entry, not a silent edit."
    }
  },

  "output_schema": {
    "change_area_release_table": {
      "columns": [
        "from_class",
        "to_class",
        "adjusted_area_hectares",
        "standard_error_hectares",
        "ci_lower_hectares",
        "ci_upper_hectares",
        "margin_of_error_percent",
        "reliability_flag",
        "raw_mapped_area_hectares"
      ]
    },
    "accuracy_summary_table": {
      "columns": [
        "class",
        "users_accuracy",
        "producers_accuracy",
        "sample_size",
        "stratum_weight"
      ]
    },
    "transition_matrix_table": {
      "description": "Square matrix, rows = from_class (T1), columns = to_class (T2), cell values = adjusted_area_hectares",
      "includes_implausible_transition_flags": true
    }
  },

  "review_and_signoff": {
    "required_reviewers": [
      "methodology reviewer (validates estimator implementation against Olofsson et al. 2014)",
      "statistical disclosure control reviewer",
      "domain/subject-matter reviewer (plausibility of transitions)"
    ],
    "signoff_required_before_release": true
  }
}

