{
  "model": "habitat-restoration-mcda",
  "aggregation_method": "weighted_linear_combination",
  "notes": "Constraints are binary masks applied after aggregation, never blended into weights. Weights below are placeholders pending stakeholder elicitation (e.g. AHP) and must sum to 1.0.",
  "factors": [
    {
      "id": "slope",
      "type": "cost",
      "direction": "lower_is_better",
      "standardization": {
        "method": "linear_min_max",
        "invert": true,
        "range": "site-specific min/max slope (degrees or percent), documented at run time"
      },
      "base_weight": 0.5
    },
    {
      "id": "habitat_quality",
      "type": "benefit",
      "direction": "higher_is_better",
      "standardization": {
        "method": "linear_min_max",
        "invert": false,
        "range": "site-specific min/max habitat quality index"
      },
      "base_weight": 0.5
    }
  ],
  "constraints": [
    {
      "id": "protected_land",
      "type": "hard_exclusion",
      "encoding": "binary_mask",
      "rule": "protected_land == true -> 0, else -> 1",
      "applied": "multiplied against aggregated suitability surface as the final step"
    }
  ],
  "sensitivity_analysis": {
    "method": "one_at_a_time",
    "perturbation": {
      "type": "relative",
      "magnitude": 0.20,
      "directions": ["+20%", "-20%"]
    },
    "renormalization": "after perturbing one factor's weight, rescale remaining factor weights proportionally so all weights sum to 1.0",
    "runs": [
      {
        "id": "slope_plus20",
        "weights": { "slope": 0.6, "habitat_quality": 0.4 }
      },
      {
        "id": "slope_minus20",
        "weights": { "slope": 0.4, "habitat_quality": 0.6 }
      },
      {
        "id": "habitat_quality_plus20",
        "weights": { "slope": 0.4, "habitat_quality": 0.6 }
      },
      {
        "id": "habitat_quality_minus20",
        "weights": { "slope": 0.6, "habitat_quality": 0.4 }
      }
    ],
    "outputs": [
      "suitability_class_change_percent_area",
      "stability_map (cells whose suitability class never changes across all perturbation runs)",
