{
  "product": {
    "name": "monthly_snow_cover_composite",
    "version": "1.0.0",
    "description": "Monthly snow cover composite derived from daily optical surface-reflectance imagery using the Normalized Difference Snow Index (NDSI).",
    "temporal_resolution": "monthly",
    "compositing_period": {
      "definition": "calendar month, UTC",
      "start_rule": "first day of month 00:00:00Z",
      "end_rule": "first day of next month 00:00:00Z (exclusive)"
    }
  },

  "source": {
    "primary_collection": "sentinel-2-l2a",
    "processing_level": "L2A (bottom-of-atmosphere surface reflectance)",
    "stac_endpoint": "https://earth-search.aws.element84.com/v1",
    "search_parameters": {
      "collections": ["sentinel-2-l2a"],
      "datetime": "{month_start}/{month_end}",
      "query": { "eo:cloud_cover": { "lt": 80 } },
      "note": "Scene-level cloud_cover is used only to skip near-total-cloud scenes cheaply; the authoritative per-pixel mask is the SCL band, not this metadata field."
    },
    "required_bands": {
      "green": "B03",
      "swir1": "B11",
      "nir": "B08",
      "scl": "SCL"
    },
    "resolution_policy": {
      "target_resolution_m": 20,
      "reasoning": "B11 (SWIR1) is native 20 m; compositing at 20 m avoids upsampling B11 into a false 10 m NDSI. B03 and B08 (native 10 m) are downsampled to 20 m to match."
    },
    "reflectance_conversion": {
      "formula": "reflectance = (DN + BOA_ADD_OFFSET) / QUANTIFICATION_VALUE",
      "rule": "Read BOA_ADD_OFFSET and QUANTIFICATION_VALUE from each scene's own metadata (MTD_MSIL2A.xml or STAC item properties). Do not hardcode -1000 / 10000.",
      "harmonized_collections_warning": "If sourcing from a pre-harmonized collection (e.g. Earth Engine COPERNICUS/S2_SR_HARMONIZED), the offset has already been applied — do not apply it a second time.",
      "baseline_manifest_requirement": "Record the Sentinel-2 processing baseline (e.g. '05.00') of every scene ingested, in addition to product level, in the per-run manifest."
    }
  },

  "cloud_and_quality_masking": {
    "method": "SCL (Scene Classification Layer) class filter",
    "reproducibility_note": "Mask is a fixed, versioned list of excluded SCL class codes applied identically to every scene and every run — no scene-adaptive or manual thresholding.",
    "excluded_scl_classes": {
      "0": "no_data",
      "1": "saturated_or_defective",
      "2": "dark_area_pixels",
      "3": "cloud_shadow",
      "8": "cloud_medium_probability",
      "9": "cloud_high_probability",
      "10": "thin_cirrus"
    },
    "retained_scl_classes": {
      "4": "vegetation",
      "5": "bare_soil",
      "6": "water",
      "7": "unclassified",
      "11": "snow_ice"
    },
    "class_11_note": "SCL class 11 (snow/ice) is explicitly RETAINED as a valid observation, unlike generic land-cover masking recipes that drop it — dropping it here would systematically remove the target class.",
    "scene_inclusion_threshold": {
      "min_valid_pixel_fraction": 0.60,
      "rule": "A scene is excluded from the monthly stack entirely if fewer than 60% of its pixels (within the analysis extent) pass the SCL filter. Logged per scene in the run manifest."
    }
  },

  "index": {
    "name": "NDSI",
    "formula": "(green - swir1) / (green + swir1)",
    "input_bands": { "a": "B03 (green)", "b": "B11 (swir1)" },
    "zero_denominator_handling": "where (green + swir1) == 0, output NaN (excluded from valid observation count)",
    "computed_on": "surface reflectance (post BOA_ADD_OFFSET / QUANTIFICATION_VALUE conversion), not raw DN"
  },

  "snow_classification": {
    "rule": "ndsi >= 0.40",
    "threshold": 0.40,
    "output_domain": "per-pixel, per-daily-observation, prior to monthly aggregation",
    "false_positive_guardrail": {
      "recommended": true,
      "condition": "nir_reflectance > 0.11",
      "reasoning": "Water and some dark surfaces can exceed NDSI 0.40; a minimum NIR reflectance check (standard in MODIS/VIIRS snow algorithms) suppresses most water false positives. Applied as an AND condition alongside the NDSI threshold when nir band is available.",
      "band": "B08"
    },
    "pixel_states": {
      "snow": "ndsi >= 0.40 (and nir guardrail passes, if enabled)",
      "no_snow": "valid observation, ndsi < 0.40",
      "invalid": "excluded by cloud/quality mask, or zero-denominator NDSI"
    }
  },

  "monthly_aggregation": {
    "method": "per-pixel temporal stacking over all daily scenes within the calendar month",
    "reproducibility_note": "Deterministic reduction only (counts, sums, ratios). No order-dependent operations (no 'first valid', 'last valid', or 'most recent') so output does not depend on scene processing order.",
    "steps": [
      "1. For each pixel and each daily scene in the month, classify as snow / no_snow / invalid per snow_classification and cloud_and_quality_masking rules.",
      "2. valid_observation_count = count of daily observations classified snow or no_snow (i.e. not invalid) at that pixel.",
      "3. snow_observation_count = count of daily observations classified snow at that pixel.",
      "4. snow_frequency = snow_observation_count / valid_observation_count (NaN if valid_observation_count == 0).",
      "5. monthly_snow_flag = 1 if snow_frequency >= 0.5, else 0 (majority rule), else nodata if valid_observation_count == 0."
    ],
    "minimum_valid_observations": {
      "value": 3,
      "rule": "If valid_observation_count < 3 for a pixel in the month, monthly_snow_flag and snow_frequency are set to nodata regardless of the majority rule, to avoid single-scene noise driving the monthly label."
    }
  },

  "output": {
    "format": "GeoTIFF (COG), one file per month per tile",
    "filename_pattern": "snow_composite_{tile_id}_{yyyy}-{mm}.tif",
    "crs": "source tile UTM zone (native Sentinel-2 tiling grid, no reprojection)",
    "resolution_m": 20,
    "bands": [
      {
        "index": 1,
        "name": "monthly_snow_flag",
        "dtype": "uint8",
        "values": { "0": "no_snow", "1": "snow", "255": "nodata" },
        "nodata": 255
      },
      {
        "index": 2,
        "name": "snow_frequency",
        "dtype": "float32",
        "range": [0.0, 1.0],
        "description": "fraction of valid daily observations classified as snow in the month",
        "nodata": "NaN"
      },
      {
        "index": 3,
        "name": "valid_observation_count",
        "dtype": "uint8",
        "description": "count of cloud/quality-mask-passing daily observations contributing to the pixel in the month",
        "nodata": 0
      }
    ]
  },

  "reproducibility_manifest": {
    "required_per_run": [
      "list of STAC item IDs ingested (collection + id + datetime)",
      "Sentinel-2 processing baseline per scene",
      "BOA_ADD_OFFSET and QUANTIFICATION_VALUE per scene per band",
      "SCL excluded/retained class list (versioned, see cloud_and_quality_masking)",
      "scene_inclusion_threshold outcome per scene (included/excluded + valid_pixel_fraction)",
      "NDSI threshold and NIR guardrail setting used",
      "minimum_valid_observations threshold used",
      "code/spec version hash",
      "output CRS and resolution"
    ],
    "storage": "written alongside each output GeoTIFF as {filename}.manifest.json"
  },

  "known_limitations": [
    "NDSI >= 0.40 alone can misclassify open water and some wet dark surfaces as snow without the NIR guardrail; enable nir_reflectance guardrail for water-adjacent areas.",
    "Thin or broken cloud not flagged by SCL (medium/high probability classes) can pass the mask and depress or inflate snow_frequency for affected days.",
    "Terrain shadow in mountainous terrain can suppress NDSI and cause under-detection of snow on shadowed slopes; consider a topographic correction upstream if the study area is mountainous.",
    "Majority-rule (snow_frequency >= 0.5) monthly flag is sensitive to observation count; pixels near the minimum_valid_observations threshold carry higher label uncertainty than pixels with many clear-sky days.",
    "20 m output resolution reflects the native resolution of B11; do not present this product as 10 m resolution."
  ]
}

