{
  "specification": {
    "title": "Land-Cover Change Area Estimation and Public Release Specification",
    "version": "1.0.0",
    "status": "draft",
    "purpose": "Define the methodology, inputs, quality controls, and output contract required to report statistically defensible changed-hectares estimates derived from two independently validated land-cover maps, suitable for public statistical release.",
    "scope_note": "This spec governs post-classification change-area estimation. It does not govern the classification algorithms used to produce the two input maps, only their accuracy documentation and use in area estimation.",

    "principles": [
      "Area must never be reported by simple pixel-counting of a change map; classification error biases pixel counts and must be corrected using an error-adjusted (unbiased) estimator.",
      "Every reported area estimate must be accompanied by a standard error and confidence interval.",
      "The two input maps must have been validated independently (independent reference samples and/or independent interpreters) so their errors are not artificially correlated.",
      "All methodology, sample design, and class definitions must be disclosed alongside the figures to allow reproducibility.",
      "Small or statistically unreliable estimates must be flagged or suppressed rather than published without qualification."
    ],

    "methodology": {
      "framework": "Good Practice Recommendations for Assessing and Reporting Land-Cover/Land-Change Area and Accuracy (Olofsson et al., 2013/2014)",
      "estimator": "stratified-area estimator using the multi-date error (confusion) matrix, with map strata = combinations of time-1 class x time-2 class",
      "change_definition": "A unit of area is 'changed' if its validated (reference-adjusted) class label at time 2 differs from its validated class label at time 1. Change is reported per transition (from_class -> to_class) and as aggregate net and gross change.",
      "unbiased_area_formula": "Area_hat(class_k) = A_total * sum_i( (n_ik / n_i) * W_i )  -- where W_i is the mapped proportion of area in stratum i, n_i is the reference sample size in stratum i, and n_ik is the count of reference samples in stratum i labeled class k",
      "standard_error_formula": "SE(Area_hat) computed via the stratified random sampling variance estimator (Olofsson eq. 10), propagated to hectares by multiplying by A_total",
      "confidence_level": 0.95,
      "gross_vs_net_change": "Report both gross gain, gross loss, and net change per class; net change alone must not be published without the corresponding gross figures, since net change can mask large but offsetting transitions."
    },

    "inputs": {
      "map_t1": {
        "description": "First-date land-cover classification map",
        "required_fields": ["dataset_id", "acquisition_date_range", "sensor", "spatial_resolution_m", "crs", "class_legend", "classification_method", "producer"],
        "accuracy_assessment": {
          "reference_sample_design": "probability sample (e.g., stratified random) independent of map_t2 reference sample",
          "required_outputs": ["confusion_matrix", "overall_accuracy", "per_class_user_accuracy", "per_class_producer_accuracy", "sample_size_per_stratum"]
        }
      },
      "map_t2": {
        "description": "Second-date land-cover classification map",
        "required_fields": ["dataset_id", "acquisition_date_range", "sensor", "spatial_resolution_m", "crs", "class_legend", "classification_method", "producer"],
        "accuracy_assessment": {
          "reference_sample_design": "probability sample (e.g., stratified random) independent of map_t1 reference sample",
          "required_outputs": ["confusion_matrix", "overall_accuracy", "per_class_user_accuracy", "per_class_producer_accuracy", "sample_size_per_stratum"]
        }
      },
      "independence_requirement": "map_t1 and map_t2 must use distinct reference sample draws and, where feasible, distinct interpreters/labeling sessions, to avoid shared-error bias in the multi-date matrix. This must be documented under provenance.independence_statement.",
      "co_registration_requirement": "Both maps must share identical CRS, pixel grid, and spatial extent prior to overlay; any resampling method used must be recorded in provenance."
    },

    "processing_steps": [
      "1. Verify co-registration (identical grid/CRS/extent) of map_t1 and map_t2; resample if required and log the method.",
      "2. Overlay maps to derive the mapped transition strata (time1_class x time2_class) and compute mapped area proportions W_i per stratum.",
      "3. Draw or reuse an independent, valid reference sample of the overlay strata (probability sampling; document design in accuracy_assessment).",
      "4. Interpret reference sample units for both dates independently to build the multi-date error matrix.",
      "5. Compute the stratified unbiased area estimate and standard error for each transition class using the formulas in methodology.",
      "6. Convert estimates to hectares using the pixel/unit area and total mapped area (A_total).",
      "7. Aggregate to gross gain, gross loss, and net change per class; compute 95% confidence intervals.",
      "8. Apply disclosure_control checks (reliability and suppression rules) before publication.",
      "9. Populate the output_schema table and accompanying metadata for release."
    ],

    "output_schema": {
      "type": "array",
      "description": "One row per land-cover transition (including 'no change' rows), forming the public release table.",
      "items": {
        "type": "object",
        "required": [
          "from_class",
          "to_class",
          "area_hectares",
          "standard_error_hectares",
          "confidence_interval_95_hectares",
          "margin_of_error_pct",
          "reliability_flag"
        ],
        "properties": {
          "from_class": { "type": "string", "description": "Time-1 land-cover class label" },
          "to_class": { "type": "string", "description": "Time-2 land-cover class label" },
          "area_hectares": { "type": "number", "description": "Error-adjusted (unbiased) area estimate in hectares" },
          "standard_error_hectares": { "type": "number" },
          "confidence_interval_95_hectares": {
            "type": "object",
            "properties": {
              "lower": { "type": "number" },
              "upper": { "type": "number" }
            }
          },
          "margin_of_error_pct": { "type": "number", "description": "95% CI half-width as a percentage of area_hectares" },
          "reliability_flag": {
            "type": "string",
            "enum": ["reliable", "low_reliability", "suppressed"],
            "description": "Set per disclosure_control.reliability_rules"
          }
        }
      }
    },

    "disclosure_control": {
      "reliability_rules": [
        "Flag as 'low_reliability' any estimate whose margin_of_error_pct exceeds 30% or whose contributing reference sample count in any stratum is below 10 (per Olofsson good-practice minimum sample guidance).",
