{
  "title": "Route Circuity Comparison: January vs July",
  "objective": "Determine whether observed route circuity (ratio of actual travel distance to straight-line origin-destination distance) differs between January and July, while isolating that difference from two known confounds: unequal GPS sampling intervals and a road network update in April.",
  "circuity_definition": {
    "formula": "circuity_index = network_travel_distance / great_circle_distance(origin, destination)",
    "notes": "network_travel_distance should be derived from map-matched route geometry, not raw GPS point-to-point summation, so that it is insensitive to sampling interval (see confound_1)."
  },
  "confounds": [
    {
      "id": "confound_1_sampling_rate",
      "description": "January traces are sampled every 5s, July every 60s. Summing straight-line chords between consecutive raw GPS points systematically underestimates path length on curved/winding roads, and the underestimate grows with sampling interval. A naive comparison would make July routes look artificially less circuitous than January routes purely due to coarser sampling, not real routing behavior.",
      "mitigation": [
        "Do not compute distance by summing raw consecutive-point chords.",
        "Map-match each trace to the road network in effect for that period, then compute travel distance along the matched network edges (this recovers the true path length regardless of point density).",
        "As a diagnostic, also compute the naive chord-sum distance for both months and report the chord-sum-to-map-matched ratio per month to quantify how much the sampling gap would have biased results if uncorrected.",
        "Optionally validate on a subset of January traces by downsampling them to 60s and confirming map-matched circuity is stable (sanity check that the correction works)."
      ]
    },
    {
      "id": "confound_2_network_update",
      "description": "The road network was updated in April, i.e., between the January and July observation windows. Map-matching and shortest-path/circuity calculations depend on network topology, so using a single current network snapshot for both months would apply post-update geometry to pre-update trips (or vice versa), conflating real behavioral/seasonal circuity differences with artifacts of the network change.",
      "mitigation": [
        "Use the pre-April network snapshot to map-match and compute network distances for January trips, and the post-April snapshot for July trips (each month evaluated against the network that was actually in place).",
        "Separately, run a sensitivity analysis applying the post-April network to both months (re-matching January traces against the July network) to estimate how much of any January-vs-July circuity difference is attributable to the network update itself versus genuine seasonal/route-choice differences.",
        "Diff the two network snapshots (added/removed/modified edges, new restrictions, closures) and flag OD pairs whose matched routes cross an area with material network changes; treat circuity deltas for those pairs cautiously in interpretation."
      ]
    }
  ],
  "methodology": [
    {
      "step": 1,
      "name": "Data preparation",
      "tasks": [
        "Load January GPS traces (5s sampling) and July GPS traces (60s sampling).",
        "Load pre-April and post-April road network snapshots.",
        "Segment each raw trace into discrete trips (origin/destination pairs) using standard stop/gap detection."
      ]
    },
    {
      "step": 2,
      "name": "Map matching",
      "tasks": [
        "Map-match January trips to the pre-April network.",
        "Map-match July trips to the post-April network.",
        "Discard or flag trips with low map-matching confidence, especially those affected by the coarse 60s sampling."
      ]
    },
    {
      "step": 3,
      "name": "Distance computation",
      "tasks": [
        "Compute network_travel_distance per trip from matched edge geometry.",
        "Compute great_circle_distance per trip from trip origin/destination coordinates.",
        "Compute circuity_index per trip.",
        "Compute naive chord-sum distance per trip for the sampling-bias diagnostic."
      ]
    },
    {
      "step": 4,
      "name": "Aggregation and comparison",
      "tasks": [
        "Summarize circuity_index distribution (mean, median, IQR) for January and July.",
        "Test for statistically significant difference (e.g., Mann-Whitney U, given likely non-normal circuity distributions).",
        "Break down by trip distance bands, since circuity typically varies with trip length."
      ]
    },
    {
      "step": 5,
      "name": "Confound isolation / sensitivity checks",
      "tasks": [
        "Report chord-sum-vs-map-matched bias by month (confound_1 diagnostic).",
        "Re-run July network on January traces and compare to the primary result (confound_2 diagnostic).",
        "Flag and separately report circuity deltas for OD pairs crossing network-change areas."
      ]
    },
    {
      "step": 6,
      "name": "Reporting",
      "tasks": [
        "Produce final circuity comparison with confidence intervals.",
        "Explicitly state how much of the January-July difference (if any) is explained by sampling-rate correction and network-update sensitivity checks versus residual, presumed-behavioral difference."
      ]
    }
  ],
  "outputs": [
    "circuity_summary_by_month.csv",
    "circuity_by_distance_band.csv",
    "sampling_bias_diagnostic.csv",
    "network_sensitivity_check.csv",
    "network_diff_flagged_od_pairs.csv",
    "final_report.md"
  ],
  "open_questions_for_user": [
    "Where are the January/July GPS trace files and the pre-/post-April network snapshots located (paths or data source)?",
    "What map-matching tool/library should be used (e.g., existing pipeline, OSRM, Valhalla, custom)?",
    "Should trips be filtered by minimum distance or duration before inclusion?",
    "Is there a specific significance level or confidence interval convention to follow for this analysis?"
  ]
}

