"""Ingest a WKT geometry into an allow-listed PostGIS table.

Enforces the ingest contract: only `public.parcels` may be written to,
only SRIDs 4326/3857 are accepted as input, geometry is validated and
normalized to a MULTIPOLYGON in SRID 3857, and any database failure rolls
back the transaction and is re-raised with context.
"""

from __future__ import annotations

import psycopg
from psycopg import sql

ALLOWED_TABLES = frozenset({"public.parcels"})
ALLOWED_SOURCE_SRIDS = frozenset({4326, 3857})
TARGET_SRID = 3857
ALLOWED_GEOMETRY_TYPES = frozenset({"POLYGON", "MULTIPOLYGON"})


class DisallowedTableError(ValueError):
    """Raised when table_name is not on the ingest allow-list."""


class UnsupportedSRIDError(ValueError):
    """Raised when source_srid is not one of the supported SRIDs."""


class InvalidGeometryError(ValueError):
    """Raised when geometry_wkt cannot be parsed, is invalid, or is the wrong type."""


class IngestFailedError(RuntimeError):
    """Raised when the insert fails at the database; the transaction is rolled back."""


def _table_identifier(table_name: str) -> sql.Composed:
    schema, sep, table = table_name.partition(".")
    if not sep:
        return sql.Identifier(schema)
    return sql.Identifier(schema, table)


def _validate_geometry(conn, source_srid: int, geometry_wkt: str) -> None:
    try:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT ST_IsValid(g), GeometryType(g) "
                "FROM (SELECT ST_GeomFromText(%s, %s) AS g) AS parsed",
                (geometry_wkt, source_srid),
            )
            row = cur.fetchone()
    except psycopg.Error as exc:
        conn.rollback()
        raise InvalidGeometryError(
            f"geometry_wkt could not be parsed as WKT: {geometry_wkt!r}"
        ) from exc

    if row is None:
        conn.rollback()
        raise InvalidGeometryError(f"geometry_wkt produced no geometry: {geometry_wkt!r}")

    is_valid, geom_type = row
    if not is_valid or geom_type not in ALLOWED_GEOMETRY_TYPES:
        conn.rollback()
        raise InvalidGeometryError(
            f"geometry_wkt is not a valid polygonal geometry "
            f"(valid={is_valid}, type={geom_type}): {geometry_wkt!r}"
        )


def ingest_geometry(conn, table_name, source_srid, geometry_wkt):
    """Insert `geometry_wkt` into `table_name` as a 3857 MULTIPOLYGON.

    Raises DisallowedTableError, UnsupportedSRIDError, or InvalidGeometryError
    for bad input before any write is attempted. Raises IngestFailedError,
    with the transaction rolled back, if the database insert itself fails.
    """
    if table_name not in ALLOWED_TABLES:
        raise DisallowedTableError(
            f"table {table_name!r} is not in the ingest allow-list {sorted(ALLOWED_TABLES)}"
        )
    if source_srid not in ALLOWED_SOURCE_SRIDS:
        raise UnsupportedSRIDError(
            f"source_srid {source_srid!r} is not one of the supported SRIDs "
            f"{sorted(ALLOWED_SOURCE_SRIDS)}"
        )

    _validate_geometry(conn, source_srid, geometry_wkt)

    insert_sql = sql.SQL(
        "INSERT INTO {table} (geom) "
        "VALUES (ST_Multi(ST_Transform(ST_GeomFromText(%s, %s), %s)))"
    ).format(table=_table_identifier(table_name))

    try:
        with conn.cursor() as cur:
            cur.execute(insert_sql, (geometry_wkt, source_srid, TARGET_SRID))
        conn.commit()
    except psycopg.Error as exc:
        conn.rollback()
        raise IngestFailedError(
            f"failed to ingest geometry into {table_name}: {exc}"
        ) from exc
